var lights=UnityEngine.Object.FindObjectsByType<UnityEngine.Light>();
return new {playing=UnityEditor.EditorApplication.isPlaying,scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path,sky=UnityEngine.RenderSettings.skybox!=null?UnityEngine.RenderSettings.skybox.shader.name:"none",exposure=UnityEngine.RenderSettings.skybox!=null&&UnityEngine.RenderSettings.skybox.HasProperty("_Exposure")?UnityEngine.RenderSettings.skybox.GetFloat("_Exposure"):-1,sun=UnityEngine.RenderSettings.sun!=null?UnityEngine.RenderSettings.sun.name:"none",ambientMode=UnityEngine.RenderSettings.ambientMode.ToString(),ambient=UnityEngine.RenderSettings.ambientIntensity,skyColor=UnityEngine.RenderSettings.ambientSkyColor.ToString(),lights=System.Array.ConvertAll(lights,l=>new {l.name,type=l.type.ToString(),l.intensity,mode=l.lightmapBakeType.ToString()}),lightmaps=UnityEngine.LightmapSettings.lightmaps.Length};
